def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def as_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            for ax, ay in (("x", "y"), ("row", "col"), ("r", "c")):
                if ax in v and ay in v:
                    return v[ax], v[ay]
        return None

    def flatten_positions(x):
        out = []
        if x is None:
            return out
        if isinstance(x, dict):
            p = as_pair(x)
            if p is not None:
                out.append(p)
            else:
                for v in x.values():
                    out.extend(flatten_positions(v))
            return out
        if isinstance(x, (list, tuple)):
            p = as_pair(x)
            if p is not None:
                out.append(p)
            else:
                for v in x:
                    out.extend(flatten_positions(v))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(dx, dy):
        if dx < -1: dx = -1
        if dx > 1: dx = 1
        if dy < -1: dy = -1
        if dy > 1: dy = 1
        return dx, dy

    def get_self_pos(obs):
        for key in ("self", "agent", "player", "me"):
            v = g(obs, key)
            if v is not None:
                p = as_pair(v)
                if p is not None:
                    return p
                if isinstance(v, dict):
                    for key2 in ("position", "pos", "location", "loc", "xy"):
                        p = as_pair(g(v, key2))
                        if p is not None:
                            return p
        for key in ("position", "pos", "location", "loc", "xy"):
            p = as_pair(g(obs, key))
            if p is not None:
                return p
        return (0, 0)

    def get_grid(obs):
        for key in ("grid", "map", "board", "terrain", "cells"):
            v = g(obs, key)
            if isinstance(v, (list, tuple)) and v:
                return v
        return None

    def in_bounds(grid, x, y):
        try:
            return 0 <= y < len(grid) and 0 <= x < len(grid[0])
        except Exception:
            return True

    def cell_at(grid, x, y):
        try:
            return grid[y][x]
        except Exception:
            return None

    def blocked(cell):
        if cell is None:
            return False
        if isinstance(cell, bool):
            return cell
        if isinstance(cell, (int, float)):
            return cell < 0
        if isinstance(cell, str):
            s = cell.lower()
            return s in ("#", "x", "wall", "blocked", "obstacle", "water")
        if isinstance(cell, dict):
            for k in ("blocked", "wall", "obstacle", "impassable"):
                if g(cell, k, False):
                    return True
        return False

    pos = get_self_pos(observation)
    grid = get_grid(observation)

    # Collect potential targets and threats from many possible schemas.
    resources = []
    for key in ("resources", "resource", "food", "coins", "treasures", "targets", "objective", "objectives"):
        resources.extend(flatten_positions(g(observation, key)))

    enemies = []
    for key in ("enemies", "enemy", "opponents", "opponent", "pursuers", "agents", "players", "others"):
        raw = g(observation, key)
        if isinstance(raw, (list, tuple)):
            for item in raw:
                if isinstance(item, dict):
                    # Prefer explicit hostile markers, but accept all other agents.
                    p = None
                    for pk in ("position", "pos", "location", "loc", "xy"):
                        p = as_pair(g(item, pk))
                        if p is not None:
                            break
                    if p is None:
                        p = as_pair(item)
                    if p is not None and p != pos:
                        enemies.append(p)
                else:
                    p = as_pair(item)
                    if p is not None and p != pos:
                        enemies.append(p)
        else:
            enemies.extend(flatten_positions(raw))

    # Territory control may have frontier / unowned / enemy territory info.
    frontier = []
    for key in ("frontier", "border", "neutral", "unclaimed", "capture_points", "flags", "zones"):
        frontier.extend(flatten_positions(g(observation, key)))

    # Build candidate moves.
    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = pos[0] + dx, pos[1] + dy
            ok = True
            if grid is not None and not in_bounds(grid, nx, ny):
                ok = False
            if ok and grid is not None:
                c = cell_at(grid, nx, ny)
                if blocked(c):
                    ok = False
            if ok:
                candidates.append((dx, dy, (nx, ny)))

    if not candidates:
        return [0, 0]

    # Default anchors.
    center = None
    if grid is not None:
        try:
            center = (len(grid[0]) // 2, len(grid) // 2)
        except Exception:
            center = None

    # Decide mode implicitly by available info.
    mode = "territory"
    if resources:
        mode = "resource"
    elif enemies:
        mode = "pursuit"

    best = None
    best_score = None

    for dx, dy, np in candidates:
        score = 0

        # Small preference for movement over idle.
        if dx == 0 and dy == 0:
            score -= 0.25

        if mode == "resource" and resources:
            d = min(manhattan(np, r) for r in resources)
            score -= d * 2.0
            # Gentle attraction to center if no obvious resource.
        elif mode == "pursuit" and enemies:
            d = min(manhattan(np, e) for e in enemies)
            # If enemy list likely pursuers, avoid; otherwise pursue by being closer when far.
            if len(enemies) <= 2:
                score -= d * 0.5
            else:
                score += d * 1.5
            # Also prefer staying away from adjacency unless clearly pursuing.
            if d == 0:
                score -= 3
        else:
            if frontier:
                d = min(manhattan(np, t) for t in frontier)
                score -= d * 1.5
            elif center is not None:
                score -= manhattan(np, center) * 0.1

        # Repel from enemies generally.
        if enemies:
            nearest_enemy = min(manhattan(np, e) for e in enemies)
            score += nearest_enemy * 0.6
            if nearest_enemy <= 1:
                score -= 4

        # Mild wall-hugging penalty if grid known and next to border.
        if grid is not None:
            try:
                w = len(grid[0])
                h = len(grid)
                edge = min(np[0], np[1], w - 1 - np[0], h - 1 - np[1])
                score += edge * 0.05
            except Exception:
                pass

        # Tie-breakers favor lexicographically smaller deterministic moves.
        key = (score, -abs(dx) - abs(dy), -dx, -dy)
        if best_score is None or key > best_score:
            best_score = key
            best = (dx, dy)

    if best is None:
        return [0, 0]
    dx, dy = clamp_move(best[0], best[1])
    return [dx, dy]

